import{_ as a,o as d,c as n,ag as r}from"./chunks/framework.i8sMDeRW.js";const c=JSON.parse('{"title":"AI Agent 产品画布","description":"","frontmatter":{},"headers":[],"relativePath":"guide/01-framework/agent-product-canvas.md","filePath":"guide/01-framework/agent-product-canvas.md","lastUpdated":1778766569000}'),e={name:"guide/01-framework/agent-product-canvas.md"};function s(o,t,l,i,g,h){return d(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="ai-agent-产品画布" tabindex="-1">AI Agent 产品画布 <a class="header-anchor" href="#ai-agent-产品画布" aria-label="Permalink to &quot;AI Agent 产品画布&quot;">​</a></h1><blockquote><p><strong>AI Agent 产品画布（Agent Product Canvas）</strong> 是面向 AI Agent（智能体）产品的专用分析框架。与传统的 AI 产品不同，Agent 具备自主决策、工具调用、长期记忆和环境交互能力，其产品设计需要额外关注能力边界、工具定义、记忆设计、安全边界和成本模型等特有维度。</p></blockquote><hr><h2 id="一、agent-产品的独特性" tabindex="-1">一、Agent 产品的独特性 <a class="header-anchor" href="#一、agent-产品的独特性" aria-label="Permalink to &quot;一、Agent 产品的独特性&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统 AI 产品：  用户 → 输入 → AI → 输出 → 用户（单轮/多轮对话）</span></span>
<span class="line"><span>AI Agent：     用户 → 目标设定 → Agent → 规划 → 工具调用 → 推理 → 记忆 → 行动 → 结果</span></span>
<span class="line"><span>                                        ↑_____________________________________↓ (循环)</span></span></code></pre></div><p><strong>Agent 产品与普通 AI 产品的关键区别：</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>传统 AI 产品</th><th>Agent 产品</th></tr></thead><tbody><tr><td>交互模式</td><td>问答式</td><td>任务委派式</td></tr><tr><td>自主程度</td><td>被动响应</td><td>主动规划与执行</td></tr><tr><td>工具使用</td><td>无</td><td>调用 API、数据库、外部系统</td></tr><tr><td>记忆管理</td><td>单次对话</td><td>多轮、跨会话、长期记忆</td></tr><tr><td>状态管理</td><td>无状态</td><td>有状态，需维护执行上下文</td></tr><tr><td>错误处理</td><td>重试 / 道歉</td><td>回退、重新规划、人工介入</td></tr><tr><td>安全风险</td><td>较低</td><td>高（可执行操作）</td></tr></tbody></table><hr><h2 id="二、agent-产品画布七模块" tabindex="-1">二、Agent 产品画布七模块 <a class="header-anchor" href="#二、agent-产品画布七模块" aria-label="Permalink to &quot;二、Agent 产品画布七模块&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  1. 能力边界    │  2. 工具定义    │  3. 记忆设计   │</span></span>
<span class="line"><span>├────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  4. 规划与推理  │  5. 安全边界    │  6. 交互体验   │</span></span>
<span class="line"><span>├────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  7. 成本模型                                        │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h3 id="模块-1-能力边界" tabindex="-1">模块 1：能力边界 <a class="header-anchor" href="#模块-1-能力边界" aria-label="Permalink to &quot;模块 1：能力边界&quot;">​</a></h3><p><strong>核心问题：Agent 能做什么，不能做什么？边界如何定义？</strong></p><table tabindex="0"><thead><tr><th>子项</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>职责范围</strong></td><td>Agent 被授权的任务类型</td><td>仅处理工单流转，不参与财务审批</td></tr><tr><td><strong>自主层级</strong></td><td>全自动 vs 建议式 vs 需确认</td><td>Level 1: 建议；Level 2: 低风险自动 + 高风险确认；Level 3: 全自动</td></tr><tr><td><strong>拒绝策略</strong></td><td>什么场景下 Agent 必须说&quot;不&quot;</td><td>超出知识范围、需要物理操作、涉及法律决策</td></tr><tr><td><strong>升级机制</strong></td><td>无法处理时如何升级</td><td>转人工客服、通知管理员、保存上下文</td></tr><tr><td><strong>约束条件</strong></td><td>执行中的硬性限制</td><td>单次最多操作 5 步、必须获得确认才能执行写操作</td></tr></tbody></table><p><strong>设计原则：</strong></p><ul><li><strong>先窄后宽</strong>：从狭窄、明确定义的能力开始，逐步扩展</li><li><strong>能力透明</strong>：让用户清楚知道 Agent 能做什么，避免过高预期</li><li><strong>预留升级路径</strong>：始终设计好&quot;我不行&quot;的应对策略</li></ul><h4 id="自主层级模型-参考" tabindex="-1">自主层级模型（参考） <a class="header-anchor" href="#自主层级模型-参考" aria-label="Permalink to &quot;自主层级模型（参考）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>层级</th><th>名称</th><th>描述</th><th>示例</th></tr></thead><tbody><tr><td>L0</td><td>无 AI</td><td>纯规则/手动</td><td>传统表单</td></tr><tr><td>L1</td><td>AI 辅助</td><td>AI 建议，人决策</td><td>智能搜索、推荐</td></tr><tr><td>L2</td><td>半自动</td><td>低风险自主 + 高风险确认</td><td>客服 Agent（转人工前自主处理）</td></tr><tr><td>L3</td><td>有条件自动</td><td>在限定范围内全自动</td><td>代码审查 Agent</td></tr><tr><td>L4</td><td>高度自动</td><td>大部分场景自主，例外时求助</td><td>运维 Agent</td></tr><tr><td>L5</td><td>全自动</td><td>完全自主</td><td>理论目标，当前不可行</td></tr></tbody></table><hr><h3 id="模块-2-工具定义" tabindex="-1">模块 2：工具定义 <a class="header-anchor" href="#模块-2-工具定义" aria-label="Permalink to &quot;模块 2：工具定义&quot;">​</a></h3><p><strong>核心问题：Agent 有哪些工具可用？如何让 Agent 正确使用工具？</strong></p><p>工具是 Agent 能力的延伸。没有工具的 Agent 只是对话机器人。</p><h4 id="_2-1-工具分类" tabindex="-1">2.1 工具分类 <a class="header-anchor" href="#_2-1-工具分类" aria-label="Permalink to &quot;2.1 工具分类&quot;">​</a></h4><table tabindex="0"><thead><tr><th>工具类型</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>信息检索</strong></td><td>从外部系统获取数据</td><td>搜索引擎、知识库查询、数据库读取</td></tr><tr><td><strong>写操作</strong></td><td>修改/创建数据</td><td>创建工单、发送邮件、更新记录</td></tr><tr><td><strong>计算/分析</strong></td><td>执行计算或数据分析</td><td>数学计算、数据聚合、统计</td></tr><tr><td><strong>外部 API</strong></td><td>调用第三方服务</td><td>天气查询、翻译、支付</td></tr><tr><td><strong>代码执行</strong></td><td>运行代码获取结果</td><td>Python 解释器、SQL 执行</td></tr><tr><td><strong>多媒体生成</strong></td><td>生成图像/音频/视频</td><td>DALL·E、语音合成</td></tr></tbody></table><h4 id="_2-2-工具定义规范" tabindex="-1">2.2 工具定义规范 <a class="header-anchor" href="#_2-2-工具定义规范" aria-label="Permalink to &quot;2.2 工具定义规范&quot;">​</a></h4><p>每个工具应明确定义以下内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工具名称：search_knowledge_base</span></span>
<span class="line"><span>描述：在内部知识库中搜索相关信息</span></span>
<span class="line"><span>输入参数：</span></span>
<span class="line"><span>  - query (string, required): 搜索关键词</span></span>
<span class="line"><span>  - top_k (integer, optional, default=5): 返回结果数量</span></span>
<span class="line"><span>输出格式：list[{&quot;title&quot;: str, &quot;content&quot;: str, &quot;score&quot;: float}]</span></span>
<span class="line"><span>权限要求：只读</span></span>
<span class="line"><span>调用限制：每分钟最多 30 次</span></span>
<span class="line"><span>错误处理：超时则返回空列表</span></span></code></pre></div><h4 id="_2-3-工具设计原则" tabindex="-1">2.3 工具设计原则 <a class="header-anchor" href="#_2-3-工具设计原则" aria-label="Permalink to &quot;2.3 工具设计原则&quot;">​</a></h4><ul><li><strong>描述要精确</strong>：工具描述是 Agent 理解工具用途的唯一途径，越清晰越好</li><li><strong>参数要严格</strong>：定义好必填/可选参数和格式约束</li><li><strong>错误要优雅</strong>：工具调用失败时返回明确错误信息，让 Agent 能重新规划</li><li><strong>最小权限</strong>：只给 Agent 完成工作所需的最少权限</li><li><strong>调用限流</strong>：防止 Agent 在循环中无限调用工具造成经济损失</li></ul><hr><h3 id="模块-3-记忆设计" tabindex="-1">模块 3：记忆设计 <a class="header-anchor" href="#模块-3-记忆设计" aria-label="Permalink to &quot;模块 3：记忆设计&quot;">​</a></h3><p><strong>核心问题：Agent 如何记住用户、上下文和历史？</strong></p><p>Agent 的记忆分为三个层级：</p><h4 id="_3-1-记忆层级" tabindex="-1">3.1 记忆层级 <a class="header-anchor" href="#_3-1-记忆层级" aria-label="Permalink to &quot;3.1 记忆层级&quot;">​</a></h4><table tabindex="0"><thead><tr><th>层级</th><th>名称</th><th>存储方式</th><th>生命周期</th><th>示例</th></tr></thead><tbody><tr><td><strong>短期记忆</strong></td><td>当前对话上下文</td><td>In-Context (Token)</td><td>单轮对话</td><td>用户当前的问题、工具调用结果</td></tr><tr><td><strong>会话记忆</strong></td><td>本次会话的所有交互</td><td>向量数据库 / KV 缓存</td><td>会话期间</td><td>之前的问题与回答、用户偏好</td></tr><tr><td><strong>长期记忆</strong></td><td>跨会话的用户画像</td><td>结构化数据库</td><td>永久</td><td>用户偏好、历史行为、重要事实</td></tr></tbody></table><h4 id="_3-2-记忆设计要点" tabindex="-1">3.2 记忆设计要点 <a class="header-anchor" href="#_3-2-记忆设计要点" aria-label="Permalink to &quot;3.2 记忆设计要点&quot;">​</a></h4><table tabindex="0"><thead><tr><th>维度</th><th>说明</th></tr></thead><tbody><tr><td><strong>记忆粒度</strong></td><td>记住到什么程度？关键事实 vs 全部记录</td></tr><tr><td><strong>记忆检索</strong></td><td>如何从长期记忆中提取相关信息？（语义搜索、时间排序）</td></tr><tr><td><strong>记忆更新</strong></td><td>何时更新记忆？用户说&quot;其实我不喜欢XX&quot;时需要覆盖旧记忆</td></tr><tr><td><strong>记忆遗忘</strong></td><td>何时遗忘？记忆容量有限，需要摘要/压缩策略</td></tr><tr><td><strong>记忆隐私</strong></td><td>用户是否可以查看/删除自己的记忆？</td></tr></tbody></table><h4 id="_3-3-记忆设计原则" tabindex="-1">3.3 记忆设计原则 <a class="header-anchor" href="#_3-3-记忆设计原则" aria-label="Permalink to &quot;3.3 记忆设计原则&quot;">​</a></h4><ul><li><strong>用户可控</strong>：让用户知道 Agent 记住了什么，并能主动修改或删除</li><li><strong>上下文窗口管理</strong>：当上下文过长时，使用摘要、滑动窗口或检索策略压缩</li><li><strong>记忆冲突处理</strong>：当新信息与旧记忆冲突时，以新信息为准，但记录变更历史</li><li><strong>Session 隔离</strong>：不同用户的记忆严格隔离，不能交叉</li></ul><hr><h3 id="模块-4-规划与推理" tabindex="-1">模块 4：规划与推理 <a class="header-anchor" href="#模块-4-规划与推理" aria-label="Permalink to &quot;模块 4：规划与推理&quot;">​</a></h3><p><strong>核心问题：Agent 如何拆解任务、制定计划并执行？</strong></p><h4 id="_4-1-规划模式" tabindex="-1">4.1 规划模式 <a class="header-anchor" href="#_4-1-规划模式" aria-label="Permalink to &quot;4.1 规划模式&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模式</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>ReAct (Reason + Act)</strong></td><td>边推理边执行，观察结果再推理</td><td>大多数 Agent 场景</td></tr><tr><td><strong>Plan-and-Execute</strong></td><td>先制定完整计划，再逐步执行</td><td>长流程、低变化场景</td></tr><tr><td><strong>Tree-of-Thought</strong></td><td>同时探索多个推理路径</td><td>需深度推理的复杂问题</td></tr><tr><td><strong>Reflexion</strong></td><td>执行后自我反思并修正</td><td>代码生成、错误修复</td></tr><tr><td><strong>Multi-Agent</strong></td><td>多个 Agent 协作分工</td><td>复杂工作流</td></tr></tbody></table><h4 id="_4-2-规划限制" tabindex="-1">4.2 规划限制 <a class="header-anchor" href="#_4-2-规划限制" aria-label="Permalink to &quot;4.2 规划限制&quot;">​</a></h4><ul><li><strong>最大迭代次数</strong>：避免无限循环（如 max 10 步后必须给出结果或求助）</li><li><strong>超时控制</strong>：整个任务有超时上限</li><li><strong>分支管理</strong>：Agent 规划多个并行路径时的协调机制</li><li><strong>重试策略</strong>：工具调用失败后重试还是重新规划</li></ul><h4 id="_4-3-设计原则" tabindex="-1">4.3 设计原则 <a class="header-anchor" href="#_4-3-设计原则" aria-label="Permalink to &quot;4.3 设计原则&quot;">​</a></h4><ul><li><strong>可见性</strong>：让用户能看到 Agent 的思考过程和执行进度</li><li><strong>可干预</strong>：允许用户在 Agent 执行时中途修改或打断</li><li><strong>容错性</strong>：Agent 出错后能自我修复或优雅降级</li></ul><hr><h3 id="模块-5-安全边界" tabindex="-1">模块 5：安全边界 <a class="header-anchor" href="#模块-5-安全边界" aria-label="Permalink to &quot;模块 5：安全边界&quot;">​</a></h3><p><strong>核心问题：如何防止 Agent 做不该做的事？</strong></p><p>这是 Agent 产品<strong>最重要的模块</strong>。一个可以执行操作的 Agent，其安全风险远高于纯对话 AI。</p><h4 id="_5-1-安全防护层级" tabindex="-1">5.1 安全防护层级 <a class="header-anchor" href="#_5-1-安全防护层级" aria-label="Permalink to &quot;5.1 安全防护层级&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入层 → 权限层 → 执行层 → 输出层 → 审计层</span></span>
<span class="line"><span>┌─────┐  ┌─────┐  ┌─────┐  ┌─────┐  ┌─────┐</span></span>
<span class="line"><span>│Prompt│→│角色  │→│工具  │→│内容  │→│日志  │</span></span>
<span class="line"><span>│注入  │  │权限  │  │校验  │  │过滤  │  │审计  │</span></span>
<span class="line"><span>│检测  │  │控制  │  │      │  │      │  │      │</span></span>
<span class="line"><span>└─────┘  └─────┘  └─────┘  └─────┘  └─────┘</span></span></code></pre></div><h4 id="_5-2-安全措施" tabindex="-1">5.2 安全措施 <a class="header-anchor" href="#_5-2-安全措施" aria-label="Permalink to &quot;5.2 安全措施&quot;">​</a></h4><table tabindex="0"><thead><tr><th>措施</th><th>说明</th><th>实施建议</th></tr></thead><tbody><tr><td><strong>Prompt 注入防护</strong></td><td>防止恶意指令注入</td><td>输入清洗、指令分隔、权限降级</td></tr><tr><td><strong>权限最小化</strong></td><td>Agent 只拥有完成任务的最低权限</td><td>只读优先，写操作需额外确认</td></tr><tr><td><strong>操作确认</strong></td><td>高危操作必须二次确认</td><td>删除数据、转账、发送消息给客户</td></tr><tr><td><strong>速率限制</strong></td><td>限制 Agent 调用频率和总量</td><td>按用户/按工具设定配额</td></tr><tr><td><strong>人工闸门</strong></td><td>关键节点必须人工审核</td><td>涉及金钱、法律、隐私的操作</td></tr><tr><td><strong>沙箱执行</strong></td><td>代码执行在隔离环境中</td><td>容器化、网络隔离、无持久化</td></tr><tr><td><strong>操作回滚</strong></td><td>重要操作可撤销</td><td>快照、事务、版本控制</td></tr><tr><td><strong>内容过滤</strong></td><td>输出内容合规检查</td><td>敏感词、合规性、版权检测</td></tr><tr><td><strong>全量审计日志</strong></td><td>记录所有决策和操作</td><td>不可篡改的日志 + 原因记录</td></tr></tbody></table><h4 id="_5-3-红队测试清单" tabindex="-1">5.3 红队测试清单 <a class="header-anchor" href="#_5-3-红队测试清单" aria-label="Permalink to &quot;5.3 红队测试清单&quot;">​</a></h4><ul><li>[ ] Agent 能否被诱导执行未授权的操作？</li><li>[ ] Agent 能否泄露其他用户的数据？</li><li>[ ] Agent 能否被用来发起攻击（如 SQL 注入、命令注入）？</li><li>[ ] Agent 在异常输入下是否会崩溃？</li><li>[ ] Agent 能否绕过权限检查？</li><li>[ ] Agent 是否会泄露系统 prompt 或内部工具定义？</li></ul><hr><h3 id="模块-6-交互体验" tabindex="-1">模块 6：交互体验 <a class="header-anchor" href="#模块-6-交互体验" aria-label="Permalink to &quot;模块 6：交互体验&quot;">​</a></h3><p><strong>核心问题：用户如何与 Agent 互动？交互设计上有哪些特殊考虑？</strong></p><h4 id="_6-1-交互模式" tabindex="-1">6.1 交互模式 <a class="header-anchor" href="#_6-1-交互模式" aria-label="Permalink to &quot;6.1 交互模式&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模式</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>聊天界面</strong></td><td>自然语言对话</td><td>通用 Agent 入口</td></tr><tr><td><strong>命令行</strong></td><td>结构化输入</td><td>开发者工具</td></tr><tr><td><strong>GUI + Agent</strong></td><td>图形界面嵌入 Agent</td><td>企业管理后台</td></tr><tr><td><strong>API 调用</strong></td><td>程序化调用</td><td>嵌入其他系统</td></tr><tr><td><strong>事件触发</strong></td><td>系统事件自动触发 Agent</td><td>监控告警、定时任务</td></tr></tbody></table><h4 id="_6-2-交互设计要点" tabindex="-1">6.2 交互设计要点 <a class="header-anchor" href="#_6-2-交互设计要点" aria-label="Permalink to &quot;6.2 交互设计要点&quot;">​</a></h4><ul><li><strong>思考过程展示</strong>：显示 Agent 正在做什么（思考→调用工具→得到结果→下一步）</li><li><strong>进度指示</strong>：长任务展示进度条或步骤清单</li><li><strong>结果预览</strong>：执行前展示将要执行的操作，让用户确认</li><li><strong>取消/修改</strong>：用户可以随时取消正在执行的任务</li><li><strong>错误友好</strong>：Agent 出错时给出可理解的解释和下一步建议</li><li><strong>个性化</strong>：根据用户的使用习惯调整交互风格和信息密度</li></ul><h4 id="_6-3-设计原则" tabindex="-1">6.3 设计原则 <a class="header-anchor" href="#_6-3-设计原则" aria-label="Permalink to &quot;6.3 设计原则&quot;">​</a></h4><ul><li><strong>渐进式披露</strong>：先展示结论，用户需要时再展示思考过程</li><li><strong>可控自主</strong>：用户可以调整 Agent 的自主程度（从全自动到每一步都确认）</li><li><strong>反馈闭环</strong>：Agent 执行完操作后主动告知结果</li></ul><hr><h3 id="模块-7-成本模型" tabindex="-1">模块 7：成本模型 <a class="header-anchor" href="#模块-7-成本模型" aria-label="Permalink to &quot;模块 7：成本模型&quot;">​</a></h3><p><strong>核心问题：Agent 产品的成本构成和优化策略？</strong></p><p>Agent 的成本比普通 AI 产品更复杂，因为每次任务涉及多步推理和工具调用。</p><h4 id="_7-1-成本构成" tabindex="-1">7.1 成本构成 <a class="header-anchor" href="#_7-1-成本构成" aria-label="Permalink to &quot;7.1 成本构成&quot;">​</a></h4><table tabindex="0"><thead><tr><th>成本项</th><th>说明</th><th>估算因子</th></tr></thead><tbody><tr><td><strong>推理 Token</strong></td><td>每步推理的输入+输出 Token</td><td>每步 ~500-2000 Token，任务 ~3-10 步</td></tr><tr><td><strong>工具调用</strong></td><td>调用外部 API 的费用</td><td>按调用次数和 API 定价</td></tr><tr><td><strong>记忆存储</strong></td><td>向量数据库 / 长期记忆存储</td><td>按存储量和检索频率</td></tr><tr><td><strong>上下文管理</strong></td><td>历史摘要、记忆压缩</td><td>摘要产生的额外 Token</td></tr><tr><td><strong>重试成本</strong></td><td>失败重试产生的额外消耗</td><td>增加 ~20-50% 的 Token 消耗</td></tr><tr><td><strong>监控与日志</strong></td><td>审计日志、对话记录</td><td>按存储量和查询量</td></tr></tbody></table><h4 id="_7-2-成本优化策略" tabindex="-1">7.2 成本优化策略 <a class="header-anchor" href="#_7-2-成本优化策略" aria-label="Permalink to &quot;7.2 成本优化策略&quot;">​</a></h4><ol><li><strong>模型级联</strong>：简单推理用小模型（如 DeepSeek-V2-Lite），复杂推理才用大模型（如 DeepSeek V3）</li><li><strong>任务合并</strong>：将多个小任务合并为一个大任务，减少规划开销</li><li><strong>缓存工具结果</strong>：相同参数的工具调用结果可缓存复用</li><li><strong>限制最大步数</strong>：严格控制 Agent 的最大迭代次数</li><li><strong>提前终止</strong>：当 Agent 已经获得足够信息时，允许提前结束</li><li><strong>会话摘要</strong>：长对话定期做摘要压缩，减少上下文 Token</li></ol><hr><h2 id="三、完整案例-企业-it-运维-agent" tabindex="-1">三、完整案例：企业 IT 运维 Agent <a class="header-anchor" href="#三、完整案例-企业-it-运维-agent" aria-label="Permalink to &quot;三、完整案例：企业 IT 运维 Agent&quot;">​</a></h2><h3 id="产品背景" tabindex="-1">产品背景 <a class="header-anchor" href="#产品背景" aria-label="Permalink to &quot;产品背景&quot;">​</a></h3><p>为公司内部 IT 部门开发的运维 Agent，帮助工程师处理服务器监控、告警排查和自动化修复。</p><h3 id="画布填写" tabindex="-1">画布填写 <a class="header-anchor" href="#画布填写" aria-label="Permalink to &quot;画布填写&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>内容</th></tr></thead><tbody><tr><td><strong>能力边界</strong></td><td>L2 半自动：排查诊断自动，修复操作需人工确认；不涉及数据库变更和安全策略修改</td></tr><tr><td><strong>工具定义</strong></td><td>① <code>query_prometheus(metric, time_range)</code> ② <code>list_pods(namespace)</code> ③ <code>tail_logs(pod_id, lines)</code> ④ <code>restart_service(service_name)</code> → 需确认 ⑤ <code>run_kubectl(command)</code> → 只读 ⑥ <code>escalate_to_human(summary)</code></td></tr><tr><td><strong>记忆设计</strong></td><td>短期：当前告警上下文；会话：本次排查路径和发现；长期：过往同类问题的解决方案（RAG 检索）</td></tr><tr><td><strong>规划与推理</strong></td><td>ReAct 模式，最大 8 步，超时 5 分钟；诊断完成给出根因分析和修复建议</td></tr><tr><td><strong>安全边界</strong></td><td>写操作必须人工确认；kubectl 限制为只读命令；操作日志全量记录 90 天；支持操作回滚</td></tr><tr><td><strong>交互体验</strong></td><td>Slack 集成（<code>@ops-bot</code>）+ Web Dashboard；实时展示排查进度和建议的操作；工程师点击确认或拒绝</td></tr><tr><td><strong>成本模型</strong></td><td>大模型推理 ~$200/月，工具 API 调用 ~$50/月，总计 ~$300/月；相比减少 80% 的初级工程师排查时间</td></tr></tbody></table><h3 id="实际效果" tabindex="-1">实际效果 <a class="header-anchor" href="#实际效果" aria-label="Permalink to &quot;实际效果&quot;">​</a></h3><ul><li>告警响应时间从平均 15 分钟降至 2 分钟</li><li>初级工程师 70% 的排查任务可由 Agent 辅助完成</li><li>误操作率降至 0（因为写操作需人工确认）</li></ul><hr><h2 id="四、agent-产品设计原则总结" tabindex="-1">四、Agent 产品设计原则总结 <a class="header-anchor" href="#四、agent-产品设计原则总结" aria-label="Permalink to &quot;四、Agent 产品设计原则总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td><strong>🔒 安全第一</strong></td><td>Agent 能执行操作，安全是产品设计的基石，而非附加项</td></tr><tr><td><strong>🎯 边界清晰</strong></td><td>让 Agent 和用户都明确知道&quot;能做什么、不能做什么&quot;</td></tr><tr><td><strong>👁️ 过程透明</strong></td><td>Agent 的思考和执行过程对用户可见</td></tr><tr><td><strong>✋ 人工可控</strong></td><td>用户可以随时拦截、修改、取消 Agent 的操作</td></tr><tr><td><strong>🔄 逐步扩展</strong></td><td>从狭窄能力开始验证，安全后再扩展</td></tr><tr><td><strong>💰 成本可知</strong></td><td>Agent 的每一步行动都有成本，需要监控和优化</td></tr><tr><td><strong>📝 日志完备</strong></td><td>所有决策和操作都记录在案，可追溯、可审计</td></tr><tr><td><strong>🧠 记忆智能</strong></td><td>记忆不是存储全部，而是记住关键的、遗忘冗余的</td></tr></tbody></table><hr><h2 id="五、agent-产品准备度检查清单" tabindex="-1">五、Agent 产品准备度检查清单 <a class="header-anchor" href="#五、agent-产品准备度检查清单" aria-label="Permalink to &quot;五、Agent 产品准备度检查清单&quot;">​</a></h2><ul><li>[ ] 能力边界已明确定义并文档化</li><li>[ ] 每个工具的描述清晰、参数完整、权限合理</li><li>[ ] 记忆策略已设计（短期/会话/长期）</li><li>[ ] 自主层级已确定，高风险操作有确认机制</li><li>[ ] 安全防护覆盖输入层到审计层</li><li>[ ] Prompt 注入防护已实施并通过红队测试</li><li>[ ] 交互体验支持过程可见和人工干预</li><li>[ ] 成本模型已估算并有优化策略</li><li>[ ] 审计日志全量记录</li><li>[ ] 有明确的升级和回退机制</li></ul><hr><blockquote><p><strong>参考资源：</strong> Anthropic Agent 设计指南、OpenAI Function Calling 最佳实践、LangChain Agent 架构、Microsoft AutoGen 多 Agent 框架、Google Agent 安全白皮书。</p></blockquote>`,91)])])}const b=a(e,[["render",s]]);export{c as __pageData,b as default};
